import React, { useState, useRef, useEffect } from 'react';
import './App.css'; // Assuming you have your CSS in Modal.css
import leftArrow from './media/left.webp'; // Import your image assets
import rightArrow from './media/right.webp';
import xButton from './media/xbutton.webp'; // Import xbutton cursor

const Modal = ({ images: gridImages, initialIndex }) => {
  const [modalOpen, setModalOpen] = useState(false);
  const [currentImage, setCurrentImage] = useState(null);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [captionText, setCaptionText] = useState('');
  const [isCarousel, setIsCarousel] = useState(false);
  const [carouselImages, setCarouselImages] = useState([]);
  const modalRef = useRef(null);

  useEffect(() => {
    if (initialIndex !== undefined && gridImages && gridImages[initialIndex]) {
      openModal(initialIndex);
    }
  }, [initialIndex, gridImages]);

  const openModal = (index) => {
    if (!gridImages || !gridImages[index]) {
      console.error(`Image at index ${index} not found`);
      return;
    }

    const { backgroundImage, dataText, dataCarousel, dataImages } = gridImages[index];
    const imgSrc = backgroundImage.slice(5, -2);

    setCaptionText(dataText || 'No description available');
    setCurrentImage(imgSrc);
    setIsCarousel(dataCarousel === 'true');
    setCurrentSlideIndex(0);

    if (dataCarousel === 'true' && dataImages) {
      try {
        setCarouselImages(JSON.parse(dataImages));
      } catch (error) {
        console.error('Failed to parse data-images', error);
        return;
      }
    } else {
      setCarouselImages([]);
    }

    setModalOpen(true);
  };

  const showSlide = (index) => {
    if (carouselImages.length === 0) return;
    if (index >= carouselImages.length) setCurrentSlideIndex(0);
    if (index < 0) setCurrentSlideIndex(carouselImages.length - 1);
    else setCurrentSlideIndex(index);
  };

  const nextSlide = () => {
    showSlide(currentSlideIndex + 1);
  };

  const prevSlide = () => {
    showSlide(currentSlideIndex - 1);
  };

  const closeModal = () => {
    setModalOpen(false);
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (modalRef.current && !modalRef.current.contains(event.target)) {
        closeModal();
      }
    };

    const handleKeyDown = (event) => {
      if (modalOpen && event.key === 'Escape') {
        closeModal();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [modalOpen]);

  if (!modalOpen) return null;

  return (
    <div className={`modal ${modalOpen ? 'open' : ''}`} style={{cursor: `url(${xButton}), auto`}}>
      <div className="modal-content" ref={modalRef}>
        {isCarousel && carouselImages.length > 0 ? (
          <>
            <img className="prev" onClick={prevSlide} src={leftArrow} alt="Previous" style={{ display: 'block' }} />
            <div className="carousel-container" style={{ display: 'block' }}>
              {carouselImages.map((image, index) => (
                <div
                  key={index}
                  className="carousel-slide"
                  style={{ display: index === currentSlideIndex ? 'block' : 'none' }}
                >
                  <img src={image} alt={`Slide ${index + 1}`} />
                </div>
              ))}
            </div>
            <img className="next" onClick={nextSlide} src={rightArrow} alt="Next" style={{ display: 'block' }} />
          </>
        ) : (
          <img id="modalImg" src={currentImage} alt="Modal Image" style={{ display: 'block' }} />
        )}
        <div id="caption" style={{ display: 'block' }}>
          {captionText}
        </div>
      </div>
    </div>
  );
};

export default Modal;
